const totalPaginas = 15;
const paginas = [];
for (let i = 1; i <= totalPaginas; i++) {
  paginas.push({ json: { pagina: i, delta: 50, estado: 3 } });
}
console.log(`Generadas ${totalPaginas} páginas para scrapear`);
return paginas;

const html = $input.all()[0].json.data;
if (!html || typeof html !== 'string') return [{ json: { error: 'No HTML' } }];
if (html.includes('Web Page Blocked') || html.includes('Attack ID')) {
  console.log('WAF BLOCK detectado - saltando página');
  return [{ json: { error: 'WAF_BLOCKED', skip: true } }];
}
console.log(`HTML: ${html.length} chars`);
const convocatorias = [];
const regexLink = /<a[^>]+class=["'][^"']*detalle[^"']*["'][^>]*>([\s\S]*?)<\/a>/gi;
let m, cnt = 0;
while ((m = regexLink.exec(html)) !== null && cnt < 500) {
  cnt++;
  const linkFull = m[0], tituloHTML = m[1];
  const idM = linkFull.match(/id=["']([^"']+)["']/i);
  const idLink = idM ? idM[1] : '';
  let numExp = idLink.replace('detalleLink_','').replace('detalle_','');
  const titulo = tituloHTML.replace(/<[^>]+>/g,'').replace(/\n\s+/g,' ').replace(/\s+/g,' ').trim();
  const si = Math.max(0, m.index - 1500);
  const ei = Math.min(html.length, m.index + linkFull.length + 1500);
  const ctx = html.substring(si, ei);
  const extraer = (h, labels) => {
    for (const l of labels) {
      const p = new RegExp(`>${l}[\\s\\S]*?<span[^>]*>([^<]*)<\\/span>`,'i');
      const r = h.match(p); if (r) return r[1].trim();
    } return '';
  };
  const fechaBopa = extraer(ctx, ['Fecha de publicaci','Fecha publicaci','Fecha BOPA']);
  let np = 0;
  const npt = extraer(ctx, ['mero total de plazas:','N.º plazas:','Plazas:']);
  if (npt) np = parseInt(npt.match(/\d+/)?.[0]) || 0;
  if (!np) { const tp = titulo.match(/(\d+)\s+PLAZA/i); if (tp) np = parseInt(tp[1]); }
  let cat = 'Otros';
  const tl = titulo.toLowerCase();
  if (tl.includes('policía local')||tl.includes('policia local')) cat='Policía Local';
  else if (tl.includes('bombero')) cat='Bomberos';
  else if (tl.includes('enferm')||tl.includes('celador')||tl.includes('fisioterapeut')||tl.includes('sespa')||tl.includes('sanidad')) cat='Sanidad';
  else if (tl.includes('maestr')||tl.includes('profesor')||tl.includes('educaci')) cat='Educación';
  else if (tl.includes('administrativ')) cat='Administración General';
  else if (tl.includes('medio ambient')||tl.includes('medioambient')) cat='Medio Ambiente';
  const bopa = numExp ? `BOPA-${numExp.replace(/\//g,'-')}` : `BOPA-${Date.now()}-${cnt}`;
  if (titulo && titulo.length >= 10) {
    convocatorias.push({ json: {
      bopa_numero: bopa, titulo: titulo, organismo: 'Principado de Asturias',
      categoria: cat, url_bopa: `https://www.asturias.es/oposiciones?p_r_p_opo_id=${numExp}`,
      titulo_completo: titulo, num_plazas: np,
      fecha_publicacion: fechaBopa, fecha_scraping: new Date().toISOString()
    }});
    console.log(`[${cnt}] ${titulo} (${cat}) ${np} plazas`);
  }
}
console.log(`Total: ${convocatorias.length}`);
if (!convocatorias.length) return [{ json: { error: 'Sin resultados', skip: true } }];
return convocatorias;
